<?php use App\Support\Helpers; use App\Support\ValueFormatter; $detailPrefix = $detailPrefix ?? '/record/'; ?>
<section class="page-heading"><div><h1>Consulta de datos</h1><p class="muted"><?= $result['total'] ?> registros encontrados</p></div></section>
<form class="toolbar" method="get"><label class="search">Buscar<input name="q" value="<?= Helpers::h($search) ?>" placeholder="Buscar en las columnas visibles"></label><label>Filas por página<select name="per_page" onchange="this.form.submit()"><?php foreach ([10,25,50,100] as $size): ?><option value="<?= $size ?>" <?= $result['perPage'] === $size ? 'selected' : '' ?>><?= $size ?></option><?php endforeach; ?></select></label><button>Buscar</button></form>
<div class="table-wrap"><table class="data-table"><thead><tr><?php foreach ($columns as $column): ?><th data-column="<?= $column['id'] ?>"><a href="?<?= http_build_query(['q'=>$search,'per_page'=>$result['perPage'],'sort'=>$column['id'],'dir'=>($sort === (int)$column['id'] && $direction === 'asc') ? 'desc':'asc']) ?>"><?= Helpers::h($column['alias'] ?: $column['original_name']) ?><?= $sort === (int)$column['id'] ? ($direction === 'asc' ? ' ↑':' ↓') : '' ?></a></th><?php endforeach; ?><th>Detalle</th></tr></thead><tbody><?php foreach ($result['rows'] as $row): ?><tr><?php foreach ($columns as $column): ?><td data-column="<?= $column['id'] ?>"><?= Helpers::h(ValueFormatter::format($row['values'][(int)$column['id']] ?? null, $column)) ?></td><?php endforeach; ?><td><a href="<?= Helpers::h($detailPrefix) ?><?= $row['id'] ?>">Ver</a></td></tr><?php endforeach; ?><?php if ($result['rows'] === []): ?><tr><td colspan="<?= count($columns)+1 ?>">No hay resultados.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($result['pages'] > 1): ?><nav class="pagination" aria-label="Paginación"><?php for ($i=max(1,$result['page']-2);$i<=min($result['pages'],$result['page']+2);$i++): ?><a class="<?= $i===$result['page']?'current':'' ?>" href="?<?= http_build_query(['q'=>$search,'per_page'=>$result['perPage'],'sort'=>$sort,'dir'=>$direction,'page'=>$i]) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?>
